const int buttonPin = 2;
const int ledPin = 13;
int buttonState = 0;

void setup() {
  pinMode(ledPin, OUTPUT);
  pinMode(buttonPin, INPUT_PULLUP); // 开启内部上拉电阻
}

void loop() {
  buttonState = digitalRead(buttonPin);
  if (buttonState == LOW) {        // 按键按下为低电平
    digitalWrite(ledPin, HIGH);
  } else {
    digitalWrite(ledPin, LOW);
  }
}

const int potPin = A0;
const int ledPin = 9;

void setup() {
  pinMode(ledPin, OUTPUT);
}

void loop() {
  int sensorValue = analogRead(potPin);      // 读取电位器数值 0-1023
  int brightness = map(sensorValue, 0, 1023, 0, 255); // 映射为 0-255 亮度值
  analogWrite(ledPin, brightness);
  delay(10);
}

