#include <Adafruit_NeoPixel.h>

#define LED_PIN 9
#define LED_COUNT 12
#define SOUND_PIN A2

Adafruit_NeoPixel strip(LED_COUNT, LED_PIN, NEO_GRB + NEO_KHZ800);

int baseline = 275; // 基准值
int currentSpeed = 0;
int targetSpeed = 0;
unsigned long lastBlowTime = 0;
unsigned long lastRotationTime = 0;
int currentPosition = 0;
uint16_t hue = 0;

void setup() {
  Serial.begin(9600);

  // 初始化LED
  strip.begin();
  strip.setBrightness(100);
  strip.clear();
  strip.show();

  Serial.println("吹气控制彩虹旋转系统已启动");
  Serial.println("初始状态:彩虹灯静止");
  Serial.println("吹气:彩虹灯开始旋转，吹气力度越大旋转越快");
  Serial.println("停止吹气:彩虹灯逐渐减速至停止");
}

void loop() {
  int soundValue = analogRead(SOUND_PIN);

  Serial.print("传感器值: ");
  Serial.print(soundValue);
  Serial.print(" | 当前速度: ");
  Serial.println(currentSpeed);

  // 检测吹气
  if (soundValue > baseline + 10) {
    // 根据吹气力度计算目标速度
    int blowIntensity = soundValue - baseline;
    targetSpeed = map(blowIntensity, 10, 500, 1, 20);

    // 逐渐加速到目标速度
    if (currentSpeed < targetSpeed) {
      currentSpeed++;
    } else if (currentSpeed > targetSpeed) {
      currentSpeed--;
    }

    lastBlowTime = millis();
  } else {
    // 没有吹气，逐渐减速
    if (millis() - lastBlowTime > 500 && currentSpeed > 0) {
      currentSpeed--;
    }
  }

  // 更新LED显示
  updateLEDs();

  delay(50);
}

void updateLEDs() {
  unsigned long currentTime = millis();

  // 如果有速度且到了该旋转的时间
  if (currentSpeed > 0 && currentTime - lastRotationTime >= (1000 / currentSpeed)) {
    lastRotationTime = currentTime;

    // 清除所有LED
    strip.clear();

    // 创建旋转彩虹效果
    for (int i = 0; i < LED_COUNT; i++) {
      int ledIndex = (i + currentPosition) % LED_COUNT;
      uint16_t pixelHue = (hue + (i * 65535L / LED_COUNT)) % 65535;
      strip.setPixelColor(ledIndex, strip.gamma32(strip.ColorHSV(pixelHue, 255, 255)));
    }

    strip.show();

    // 更新位置
    currentPosition = (currentPosition + 1) % LED_COUNT;

    // 缓慢改变基础色调
    hue = (hue + 5) % 65535;
  } else if (currentSpeed == 0) {
    // 停止状态显示静态彩虹
    showStaticRainbow();
  }
}

// 显示静态彩虹
void showStaticRainbow() {
  for (int i = 0; i < LED_COUNT; i++) {
    uint16_t pixelHue = (hue + (i * 65535L / LED_COUNT)) % 65535;
    strip.setPixelColor(i, strip.gamma32(strip.ColorHSV(pixelHue, 255, 255)));
  }
  strip.show();
}
